import{_ as n,o as r,c as i,a2 as t}from"./chunks/framework.CqpfiAoK.js";const g=JSON.parse('{"title":"Kernthesen des Anti-Räuberismus","description":"","frontmatter":{},"headers":[],"relativePath":"de/04-反掠夺主义核心论纲.md","filePath":"de/04-反掠夺主义核心论纲.md","lastUpdated":1789183869000}'),s={name:"de/04-反掠夺主义核心论纲.md"};function u(d,e,a,h,o,l){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="kernthesen-des-anti-rauberismus" tabindex="-1">Kernthesen des Anti-Räuberismus <a class="header-anchor" href="#kernthesen-des-anti-rauberismus" aria-label="Permalink to &quot;Kernthesen des Anti-Räuberismus&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>04</td></tr><tr><td>Modul</td><td>Allgemeine Grundsätze und Kerneinstellungen</td></tr><tr><td>Schlüsselwörter</td><td>Anti-Räuberei, Räuberkritik, Symbiose-Alternative, Ethische Grenze, Systemrevolution</td></tr></tbody></table><h2 id="i-definition-und-erscheinungsformen-des-rauberismus" tabindex="-1">I. Definition und Erscheinungsformen des Räuberismus <a class="header-anchor" href="#i-definition-und-erscheinungsformen-des-rauberismus" aria-label="Permalink to &quot;I. Definition und Erscheinungsformen des Räuberismus&quot;">​</a></h2><p>Der Räuberismus bezieht sich auf eine Kosmosanschauung und ein Kultivierungssystem, das die unentgeltliche Aneignung, Verschlingung oder Ausbeutung des Ursprungs, der Energie, des Glücks und der Ressourcen anderer Wesen oder Ebenen als zentrales Mittel nutzt, mit dem Ziel, die Evolution des eigenen Selbst oder der eigenen Gruppe zu erreichen. Der Räuberismus ist keine spezifische Kultivierungsmethode, sondern eine grundlegende Haltung, die die Kultivierungsphilosophie, die sozialen Institutionen und die Zivilisationsbeziehungen durchdringt.</p><p>In der Geschichte von Heng Yuan Zhou manifestierte sich der Räuberismus in folgenden Hauptformen:</p><table tabindex="0"><thead><tr><th>Form</th><th>Erscheinungsform</th><th>Schaden</th></tr></thead><tbody><tr><td>Energieräuberei</td><td>Direkte Verschlingung der Kultivierungsenergie oder des Ursprungs anderer Wesen</td><td>Führt zum Tod oder zur vollständigen Zerstörung der Kultivierung des Geraubten, der kosmische Energiekreislauf wird unterbrochen</td></tr><tr><td>Glücksräuberei</td><td>Diebstahl des Glücks anderer Individuen oder Rassen durch Geheimkünste</td><td>Führt zum Zusammenbruch des Schicksals des Geraubten, zum Verfall der Rasse</td></tr><tr><td>Methodenmonopol</td><td>Einige Sekten monopolisieren die Kultivierungsmethoden und tauschen das Übertragungsrecht gegen Loyalität und Ressourcen</td><td>Führt zur Erstarrung der Schichten, die Wesen der unteren Schichten verlieren den Evolutionsweg</td></tr><tr><td>Ebenen-Kolonialismus</td><td>Höhere Ebenen erobern niedrigere Ebenen und rauben deren Ressourcen und Bevölkerung</td><td>Führt zur Beschädigung der Ebenenmembran, zum Zusammenbruch des Ökosystems der Ebene</td></tr><tr><td>Geistige Versklavung</td><td>Verwandlung anderer Wesen in Kultivierungswerkzeuge durch Seelenkontrollmittel</td><td>Entzieht dem Versklavten den freien Willen, verletzt die Würde des Lebens</td></tr><tr><td>Ressourcenerschöpfung</td><td>Rücksichtslose Ausbeutung der Ressourcen eines Planeten oder einer Ebene</td><td>Führt zum ökologischen Aussterben, beschleunigt die Zunahme der kosmischen Entropie</td></tr></tbody></table><h2 id="ii-der-grundlegende-irrtum-des-rauberismus" tabindex="-1">II. Der grundlegende Irrtum des Räuberismus <a class="header-anchor" href="#ii-der-grundlegende-irrtum-des-rauberismus" aria-label="Permalink to &quot;II. Der grundlegende Irrtum des Räuberismus&quot;">​</a></h2><p>Der Anti-Räuberismus vertritt die Ansicht, dass der Räuberismus grundsätzlich drei Irrtümer enthält:</p><h3 id="_2-1-irrtum-der-kosmosanschauung-den-kosmos-als-begrenztes-jagdrevier-betrachten" tabindex="-1">2.1 Irrtum der Kosmosanschauung: Den Kosmos als begrenztes Jagdrevier betrachten <a class="header-anchor" href="#_2-1-irrtum-der-kosmosanschauung-den-kosmos-als-begrenztes-jagdrevier-betrachten" aria-label="Permalink to &quot;2.1 Irrtum der Kosmosanschauung: Den Kosmos als begrenztes Jagdrevier betrachten&quot;">​</a></h3><p>Die Kosmosanschauung des Räuberismus betrachtet den Kosmos als ein Jagdrevier mit begrenzten Ressourcen und glaubt, dass Evolution notwendigerweise ein Nullsummenspiel ist und der Fortschritt der Starken notwendigerweise auf Kosten der Schwachen gehen muss. Diese Kosmosanschauung ignoriert die &quot;Evolvierbarkeit&quot; des Kosmos selbst — der Kosmos ist kein statischer Ressourcenbehälter, sondern ein Lebewesen, das durch ein geordnetes Symbiosenetz einen globalen Dimensionsaufstieg erreichen kann. Wenn Räuber die Schwachen verschlingen, verbrauchen sie nicht nur die Energie der Schwachen, sondern auch das Evolutionspotenzial des gesamten Kosmos.</p><h3 id="_2-2-ethischer-irrtum-das-evolutionsrecht-der-starken-uber-das-lebensrecht-der-schwachen-stellen" tabindex="-1">2.2 Ethischer Irrtum: Das Evolutionsrecht der Starken über das Lebensrecht der Schwachen stellen <a class="header-anchor" href="#_2-2-ethischer-irrtum-das-evolutionsrecht-der-starken-uber-das-lebensrecht-der-schwachen-stellen" aria-label="Permalink to &quot;2.2 Ethischer Irrtum: Das Evolutionsrecht der Starken über das Lebensrecht der Schwachen stellen&quot;">​</a></h3><p>Der Räuberismus akzeptiert das &quot;Recht des Stärkeren&quot; als Naturgesetz und glaubt, dass die Starken das Recht und sogar die Pflicht haben, die Schwachen zu verschlingen. Diese ethische Anschauung verwechselt natürliche Selektion mit moralischer Wahl. In der Natur ist das Recht des Stärkeren ein unbewusstes ökologisches Gesetz; aber in einer bewussten Kultivierungszivilisation haben die Starken die Fähigkeit zu wählen und sollten daher die Verantwortung für ihre Wahl übernehmen. Räuberei, die das &quot;Himmelsgesetz&quot; als Vorwand nimmt, ist im Wesentlichen die Verpackung der eigenen Gier der Starken als kosmisches Gesetz.</p><h3 id="_2-3-effizienzirrtum-der-glaube-dass-rauberei-der-schnellste-evolutionsweg-ist" tabindex="-1">2.3 Effizienzirrtum: Der Glaube, dass Räuberei der schnellste Evolutionsweg ist <a class="header-anchor" href="#_2-3-effizienzirrtum-der-glaube-dass-rauberei-der-schnellste-evolutionsweg-ist" aria-label="Permalink to &quot;2.3 Effizienzirrtum: Der Glaube, dass Räuberei der schnellste Evolutionsweg ist&quot;">​</a></h3><p>Der Räuberismus behauptet, dass Räuberei der schnellste und effizienteste Evolutionsweg ist. Langfristig gesehen weist die räuberische Evolution jedoch eine ernsthafte &quot;Effizienzdecke&quot; auf: Erstens trägt die durch Räuberei gewonnene Energie oft Spuren des Willens des ursprünglichen Besitzers, was einen großen Aufwand zur Veredelung und Reinigung erfordert; zweitens löst räuberisches Verhalten den Widerstand der Geraubten und ihrer verbundenen Gruppen aus und erhöht die externen Kosten der Kultivierung; drittens führt die langfristige Abhängigkeit von Räuberei zur Degeneration der eigenen Ursprungs-Evolutionsfähigkeit des Kultivierenden, der bei Verlust des Raubobjekts in die Stagnation gerät; viertens sehen sich räuberische Kultivierende beim Durchbruch zur höchsten Stufe oft mit dem Engpass der &quot;unreinen Ursprungs&quot; konfrontiert und können den kosmischen Ursprung nur schwer wirklich berühren.</p><h2 id="iii-die-kernpropositionen-des-anti-rauberismus" tabindex="-1">III. Die Kernpropositionen des Anti-Räuberismus <a class="header-anchor" href="#iii-die-kernpropositionen-des-anti-rauberismus" aria-label="Permalink to &quot;III. Die Kernpropositionen des Anti-Räuberismus&quot;">​</a></h2><p>Der Anti-Räuberismus leugnet nicht einfach allen Wettbewerb und alle Unterschiede, sondern stellt folgende Kernpropositionen auf:</p><ol><li><strong>Evolution kann nicht-Nullsumme sein</strong>: Durch den symbiotischen Kreislauf und das Ankerpunktnetz kann die Evolution der Zehntausend Rassen synergistische Effekte erzeugen und eine globale Evolutionseffizienz erreichen, die die Summe der Teile übersteigt.</li><li><strong>Wettbewerb sollte schöpferisch sein, nicht destruktiv</strong>: Der Anti-Räuberismus wendet sich nicht gegen gesunden Wettbewerb, aber die Art des Wettbewerbs sollte die Erhöhung der eigenen schöpferischen Fähigkeit sein, nicht die räuberische Fähigkeit, den Gegner zu vernichten.</li><li><strong>Die Verantwortung der Starken ist größer als ihre Rechte</strong>: Je höher die Stufe des Kultivierenden, desto größer ist seine Verantwortung für das Symbiosenetz, nicht desto größer sein Recht auf Räuberei. Fortgeschrittene Kultivierende sind verpflichtet, Anfänger zu leiten, die Stabilität der Ankerpunkte zu wahren und die Sicherheit der Zivilisation zu schützen.</li><li><strong>Ressourcen sollten durch Schöpfung vermehrt werden, nicht durch Räuberei verteilt</strong>: Der Kerngedanke der symbiotischen Zivilisation ist es, den Kuchen zu vergrößern, nicht ihn aufzuteilen; durch technologischen Fortschritt und Gesetzesanwendung werden ständig neue Kultivierungsressourcen geschaffen.</li><li><strong>Anti-Räuberismus ist kein Egalitarismus</strong>: Was der Anti-Räuberismus ablehnt, ist die Räuberei ohne Arbeit, nicht der Unterschied von Mehr Arbeit, Mehr Belohnung. Die symbiotische Zivilisation anerkennt die Unterschiede in den Evolutionsergebnissen, besteht aber darauf, dass die Unterschiede aus der eigenen Anstrengung und dem eigenen Beitrag stammen müssen.</li></ol><h2 id="iv-institutionelle-garantien-des-anti-rauberismus" tabindex="-1">IV. Institutionelle Garantien des Anti-Räuberismus <a class="header-anchor" href="#iv-institutionelle-garantien-des-anti-rauberismus" aria-label="Permalink to &quot;IV. Institutionelle Garantien des Anti-Räuberismus&quot;">​</a></h2><p>Der Anti-Räuberismus ist nicht nur eine theoretische Proposition, sondern verfügt über eine Reihe institutioneller Garantien:</p><ul><li><strong>Rechtliche Garantie</strong>: Die Symbiotische Verfassung und das Anti-Monopol-Gesetz verbieten ausdrücklich räuberisches Verhalten, das Ankergericht hat die Gerichtsbarkeit über Räuberfälle</li><li><strong>Mechanistische Garantie</strong>: Das produktionsgebundene Vertragssystem stellt sicher, dass die Ressourcenverteilung auf Beitrag而非 Gewalt basiert, das Ankerpunktnetz überwacht abnormale Energieflüsse</li><li><strong>Systemgarantie</strong>: Die Dreihundert Ursprungs-Kultivierungssysteme basieren alle auf dem Prinzip des symbiotischen Kreislaufs, es gibt keine räuberischen Methoden</li><li><strong>Bildungsgarantie</strong>: Das symbiotische Bildungssystem macht die Anti-Räuber-Ethik zu einem Pflichtfach und beseitigt räuberisches Denken von der Wurzel her</li><li><strong>Aufsichtsgarantie</strong>: Das Parlament der Republik der Zehntausend Rassen richtet eine Anti-Räuber-Kommission ein, die sich speziell der Überwachung und Untersuchung von räuberischem Verhalten widmet</li></ul><h2 id="v-politik-gegenuber-den-verbliebenen-raubermachten" tabindex="-1">V. Politik gegenüber den verbliebenen Räubermächten <a class="header-anchor" href="#v-politik-gegenuber-den-verbliebenen-raubermachten" aria-label="Permalink to &quot;V. Politik gegenüber den verbliebenen Räubermächten&quot;">​</a></h2><p>Gegenüber den im Kosmos noch verbliebenen Räubermächten verfolgt die symbiotische Zivilisation die Politik der Kombination von &quot;Isolierung, Umwandlung, Sanktion&quot;: Für Räuber, die noch keinen schweren Schaden verursacht haben, erfolgt ethische Erziehung und Systemumwandlung, um sie zur Teilnahme am symbiotischen System zu führen; für Räuber, die die Umwandlung ablehnen und die symbiotische Ordnung weiterhin schädigen, wird eine Ebenen-Isolierung und Kultivierungsbeschränkung durchgeführt; für Räuber, die schwere Katastrophen verursacht haben, wird Sanktion nach Recht verhängt. Die symbiotische Zivilisation befürwortet keine Anti-Räuberei durch Räuberei, und alle Sanktionen müssen ein faires Urteil des Ankergerichts durchlaufen.</p><h2 id="schlusswort" tabindex="-1">Schlusswort <a class="header-anchor" href="#schlusswort" aria-label="Permalink to &quot;Schlusswort&quot;">​</a></h2><p>Der Anti-Räuberismus ist einer der theoretischen Grundsteine der Anker-Symbiotischen Zivilisation. Er ist nicht nur eine Kritik am räuberischen System der alten Ära, sondern auch ein aktiver Aufbau der Möglichkeit der symbiotischen Evolution. Das ultimative Ziel des Anti-Räuberismus ist nicht die Vernichtung der Starken, sondern die Dienstbarmachung der Macht der Starken für die gemeinsame Evolution der Zehntausend Rassen.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Erklärung der Anker-Symbiotischen Zivilisation)</li><li>03-共生文明宪章 (Verfassung der Symbiotischen Zivilisation)</li><li>19-修炼伦理与边界 (Kultivierungsethik und Grenzen)</li></ul>',26)])])}const b=n(s,[["render",u]]);export{g as __pageData,b as default};
